-- v13: new AGRON™ logo — guidance texts stored in the database (run once in Supabase → SQL editor)
begin;
update public.records set data = data || jsonb_build_object('text', 'The AGRON™ logo (metal letters, orange outline, ™ mark) with the light tagline “Aerial-Ground Robotics Operations Network” is the main company logo; the version without the tagline is for small sizes. Keep the ™ mark and clear space around it; use on dark backgrounds. Do not stretch, recolour or add effects.', 'usage', 'Website, Workspace, presentations, videos, booth graphics, social media, partner materials. Download: Marketing → Brand center → Logos → AGRON™ — main logo with tagline.') where section = 'marketing.brand' and title = 'Logo use';
update public.faq set answer = 'Marketing → Brand center → Logos. Each logo has a preview, where to use it and a PNG download. The AGRON™ logo is the only company logo: keep the ™ mark; it looks best on dark backgrounds.' where lang = 'en' and source = 'seed' and (answer ilike '%white tagline%' or answer ilike '%белый слоган%' or answer ilike '%білий слоган%' or answer ilike '%بعبارة بيضاء%');
update public.faq set answer = '«Маркетинг» → «Бренд-центр» → «Логотипы». У каждого — превью, где использовать и скачивание PNG. Логотип AGRON™ — единственный логотип компании: знак ™ сохраняем; лучше всего смотрится на тёмном фоне.' where lang = 'ru' and source = 'seed' and (answer ilike '%white tagline%' or answer ilike '%белый слоган%' or answer ilike '%білий слоган%' or answer ilike '%بعبارة بيضاء%');
update public.faq set answer = '«Маркетинг» → «Бренд-центр» → «Логотипи». У кожного — прев''ю, де використовувати, і завантаження PNG. Логотип AGRON™ — єдиний логотип компанії: знак ™ зберігаємо; найкраще виглядає на темному тлі.' where lang = 'uk' and source = 'seed' and (answer ilike '%white tagline%' or answer ilike '%белый слоган%' or answer ilike '%білий слоган%' or answer ilike '%بعبارة بيضاء%');
update public.faq set answer = 'التسويق ← مركز العلامة التجارية ← الشعارات. لكل شعار معاينة ومكان الاستخدام وتنزيل PNG. شعار AGRON™ هو شعار الشركة الوحيد: نُبقي علامة ™؛ ويبدو أفضل على الخلفيات الداكنة.' where lang = 'ar' and source = 'seed' and (answer ilike '%white tagline%' or answer ilike '%белый слоган%' or answer ilike '%білий слоган%' or answer ilike '%بعبارة بيضاء%');
commit;
